# Find where the harness state is stored
import os
import glob

# Look in common locations
paths_to_check = [
    os.path.expanduser("~/.prime/agent/data"),
    os.path.expanduser("~/.prime/harness"),
    "/home/USER/.prime",
]

for path in paths_to_check:
    if os.path.exists(path):
        print(f"Found dir: {path}")
        if os.path.isfile(path):
            print(f"  Is file")
        for ext in ["*.json", "*.py"]:
            files = glob.glob(os.path.join(path, ext, "**", "*"), recursive=True)
            for f in files[:5]:
                print(f"    {os.path.basename(os.path.dirname(f))}/{os.path.basename(f)}")
